package com.uniquebattery;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class ActivityIcons
{
	private static final Map<String, Skill> SKILLS = skills();
	private static final Map<String, HiscoreSkill> BOSSES = bosses();
	private final SkillIconManager skills;
	private final SpriteManager sprites;

	@Inject
	ActivityIcons(SkillIconManager skills, SpriteManager sprites)
	{
		this.skills = skills;
		this.sprites = sprites;
	}

	void load(String activity, Consumer<Icon> showIcon)
	{
		String key = activity.toLowerCase(Locale.ROOT);
		Skill skill = SKILLS.get(key);
		if (skill != null)
		{
			showIcon.accept(new ImageIcon(skills.getSkillImage(skill, true)));
			return;
		}
		HiscoreSkill boss = BOSSES.get(key);
		if (boss != null)
		{
			sprites.getSpriteAsync(boss.getSpriteId(), 0,
				image -> SwingUtilities.invokeLater(() -> showIcon.accept(new ImageIcon(image))));
		}
	}

	private static Map<String, Skill> skills()
	{
		Map<String, Skill> icons = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			icons.put(skill.getName().toLowerCase(Locale.ROOT), skill);
		}
		return Map.copyOf(icons);
	}

	private static Map<String, HiscoreSkill> bosses()
	{
		Map<String, HiscoreSkill> icons = new HashMap<>();
		for (HiscoreSkill boss : HiscoreSkill.values())
		{
			if (boss.getType() == HiscoreSkillType.BOSS)
			{
				icons.put(boss.getName().toLowerCase(Locale.ROOT), boss);
			}
		}
		icons.put("gauntlet", HiscoreSkill.THE_GAUNTLET);
		icons.put("corrupted gauntlet", HiscoreSkill.THE_CORRUPTED_GAUNTLET);
		icons.put("fight caves", HiscoreSkill.TZTOK_JAD);
		icons.put("inferno", HiscoreSkill.TZKAL_ZUK);
		icons.put("challenge mode chambers of xeric", HiscoreSkill.CHAMBERS_OF_XERIC_CHALLENGE_MODE);
		icons.put("hard mode theatre of blood", HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE);
		icons.put("yama contract", HiscoreSkill.YAMA);
		icons.put("dawn", HiscoreSkill.GROTESQUE_GUARDIANS);
		icons.put("dusk", HiscoreSkill.GROTESQUE_GUARDIANS);
		icons.put("the mimic", HiscoreSkill.MIMIC);
		icons.put("barrows", HiscoreSkill.BARROWS_CHESTS);
		for (String brother : new String[]{"ahrim the blighted", "dharok the wretched", "guthan the infested",
			"karil the tainted", "torag the corrupted", "verac the defiled"})
		{
			icons.put(brother, HiscoreSkill.BARROWS_CHESTS);
		}
		icons.put("branda the fire queen", HiscoreSkill.THE_ROYAL_TITANS);
		icons.put("eldric the ice king", HiscoreSkill.THE_ROYAL_TITANS);
		return Map.copyOf(icons);
	}
}

package com.uniquebattery;

final class Battery
{
	static final double FULL = 100;
	private static final double TICKS_PER_MINUTE = 100;

	private Battery()
	{
	}

	static double drain(double charge, double pointsPerMinute)
	{
		return clamp(charge - pointsPerMinute / TICKS_PER_MINUTE);
	}

	static double refill(double charge, double denominator, long value, int rarityStrength, int valueStrength)
	{
		double rarityPoints = Math.min(50, 8 * Math.log10(denominator));
		double valuePoints = Math.min(50, 5 * Math.log10(1 + Math.max(0, value) / 1_000.0));
		return clamp(charge + rarityPoints * rarityStrength / 100 + valuePoints * valueStrength / 100);
	}

	static double clamp(double charge)
	{
		return Double.isFinite(charge) ? Math.max(0, Math.min(FULL, charge)) : FULL;
	}
}

package com.uniquebattery;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

final class BatteryActivityLog
{
	static final int LIMIT = 8;
	private final Deque<Entry> entries = new ArrayDeque<>();
	private final Map<String, Total> totals = new LinkedHashMap<>(16, 0.75f, true);

	void drain(String activity, double rate, double amount)
	{
		if (amount <= 0)
		{
			return;
		}
		Total total = total(activity);
		total.drained += amount;
		total.rate = rate;
		Entry latest = entries.peekFirst();
		if (latest != null && latest.rate == rate && latest.activity.equals(activity))
		{
			latest.amount += amount;
			return;
		}
		add(new Entry(activity, rate, amount));
	}

	void refill(String source, double amount)
	{
		total(source).refilled += amount;
		add(new Entry(source, 0, amount));
	}

	void reset(double amount)
	{
		add(new Entry("Manual reset", 0, amount));
	}

	private Total total(String name)
	{
		return totals.computeIfAbsent(name.toLowerCase(Locale.ROOT), key -> new Total(name));
	}

	void clear()
	{
		entries.clear();
		totals.clear();
	}

	List<Group> groups()
	{
		List<Total> ordered = new ArrayList<>(totals.values());
		List<Group> snapshot = new ArrayList<>(Math.min(ordered.size(), LIMIT));
		for (int index = ordered.size() - 1; index >= 0 && snapshot.size() < LIMIT; index--)
		{
			Total total = ordered.get(index);
			snapshot.add(new Group(total.name, total.rate, total.refilled - total.drained));
		}
		return List.copyOf(snapshot);
	}

	List<Activity> snapshot()
	{
		List<Activity> result = new ArrayList<>(entries.size());
		for (Entry entry : entries)
		{
			result.add(new Activity(entry.activity, entry.rate, entry.amount));
		}
		return List.copyOf(result);
	}

	static String rate(double rate)
	{
		return String.format(Locale.ROOT, "%.1f points/min", rate);
	}

	private void add(Entry entry)
	{
		entries.addFirst(entry);
		if (entries.size() > LIMIT)
		{
			entries.removeLast();
		}
	}

	static final class Activity
	{
		final String name;
		final double rate;
		final double amount;

		private Activity(String name, double rate, double amount)
		{
			this.name = name;
			this.rate = rate;
			this.amount = amount;
		}

		boolean isRefill()
		{
			return rate == 0;
		}

		double chargeChange()
		{
			return isRefill() ? amount : -amount;
		}

	}

	static final class Group
	{
		final String name;
		final double drainRate;
		final double net;

		private Group(String name, double drainRate, double net)
		{
			this.name = name;
			this.drainRate = drainRate;
			this.net = net;
		}
	}

	private static final class Total
	{
		private final String name;
		private double rate;
		private double drained;
		private double refilled;

		private Total(String name)
		{
			this.name = name;
		}
	}

	private static final class Entry
	{
		private final String activity;
		private final double rate;
		private double amount;

		private Entry(String activity, double rate, double amount)
		{
			this.activity = activity;
			this.rate = rate;
			this.amount = amount;
		}
	}
}

package com.uniquebattery;

import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.List;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

final class BatteryHistoryPanel extends JPanel
{
	private static final Color CHART_BACKGROUND = new Color(27, 31, 32);
	private static final Color GRID = new Color(68, 75, 76);
	private static final Color MUTED = new Color(166, 176, 177);
	private static final Color TEXT = new Color(235, 240, 241);
	private static final Color REFILL = new Color(117, 214, 154);
	private static final Color DRAIN = new Color(233, 167, 100);
	private static final Color REFILL_ROW = new Color(37, 53, 45);
	private static final Color DRAIN_ROW = new Color(53, 45, 37);
	private final ChargeTrace trace = new ChargeTrace();
	private final HistoryRow[] rows = new HistoryRow[BatteryActivityLog.LIMIT];

	BatteryHistoryPanel(ActivityIcons icons)
	{
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(12, 0, 0, 0));
		JLabel title = new JLabel("Recent activity");
		title.setFont(title.getFont().deriveFont(Font.BOLD));
		title.setBorder(new EmptyBorder(0, 1, 5, 0));
		title.setAlignmentX(LEFT_ALIGNMENT);
		add(title);
		trace.setAlignmentX(LEFT_ALIGNMENT);
		add(trace);
		add(Box.createVerticalStrut(5));
		for (int index = 0; index < rows.length; index++)
		{
			rows[index] = new HistoryRow(icons);
			add(rows[index]);
		}
	}

	void showHistory(List<BatteryActivityLog.Activity> activities, List<BatteryActivityLog.Group> groups, double charge)
	{
		setVisible(!groups.isEmpty() || !activities.isEmpty());
		trace.setVisible(!activities.isEmpty());
		trace.showHistory(activities, charge);
		for (int index = 0; index < rows.length; index++)
		{
			boolean inUse = index < groups.size();
			rows[index].setVisible(inUse);
			if (inUse)
			{
				rows[index].showGroup(groups.get(index));
			}
		}
	}

	private static final class HistoryRow extends JPanel
	{
		private final JLabel name = new JLabel();
		private final JLabel icon = new JLabel();
		private final JLabel detail = new JLabel();
		private final JLabel amount = new JLabel();
		private final JPanel body = new JPanel(new BorderLayout(4, 0));
		private final ActivityIcons icons;

		HistoryRow(ActivityIcons icons)
		{
			this.icons = icons;
			setOpaque(false);
			setAlignmentX(LEFT_ALIGNMENT);
			setLayout(new BorderLayout());
			setBorder(new EmptyBorder(0, 0, 4, 0));
			body.setBorder(new EmptyBorder(5, 7, 5, 7));
			JPanel labels = new JPanel(new BorderLayout());
			labels.setOpaque(false);
			name.setFont(name.getFont().deriveFont(Font.BOLD));
			name.setForeground(TEXT);
			detail.setForeground(MUTED);
			detail.setFont(detail.getFont().deriveFont(11f));
			labels.add(name, BorderLayout.NORTH);
			amount.setFont(amount.getFont().deriveFont(Font.BOLD));
			JPanel footer = new JPanel(new BorderLayout(4, 0));
			footer.setOpaque(false);
			footer.add(detail, BorderLayout.CENTER);
			footer.add(amount, BorderLayout.EAST);
			labels.add(footer, BorderLayout.SOUTH);
			icon.setVisible(false);
			body.add(icon, BorderLayout.WEST);
			body.add(labels, BorderLayout.CENTER);
			add(body);
		}

		void showGroup(BatteryActivityLog.Group group)
		{
			if (!group.name.equals(name.getText()))
			{
				name.setText(group.name);
				name.setToolTipText(group.name);
				icon.setIcon(null);
				icon.setVisible(false);
				icons.load(group.name, image ->
				{
					if (group.name.equals(name.getText()))
					{
						icon.setIcon(image);
						icon.setVisible(true);
					}
				});
			}
			boolean neutral = Math.abs(group.net) < 0.05;
			boolean positive = group.net > 0;
			String sign = neutral ? "" : positive ? "+" : "−";
			amount.setText(sign + String.format(Locale.ROOT, "%.1f pts", neutral ? 0.0 : Math.abs(group.net)));
			amount.setForeground(neutral ? MUTED : positive ? REFILL : DRAIN);
			body.setBackground(neutral ? CHART_BACKGROUND : positive ? REFILL_ROW : DRAIN_ROW);
			detail.setText(group.drainRate > 0 ? BatteryActivityLog.rate(group.drainRate) : "Unique refill");
		}
	}

	private static final class ChargeTrace extends JComponent
	{
		private static final int HEIGHT = 61;
		private List<BatteryActivityLog.Activity> activities = List.of();
		private double charge;

		ChargeTrace()
		{
			setPreferredSize(new Dimension(160, HEIGHT));
			setMinimumSize(new Dimension(0, HEIGHT));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
			setToolTipText("Charge across recent events and manual resets, oldest to newest");
		}

		void showHistory(List<BatteryActivityLog.Activity> recent, double currentCharge)
		{
			activities = recent;
			charge = currentCharge;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics original)
		{
			Graphics2D graphics = (Graphics2D) original.create();
			try
			{
				int width = getWidth();
				int height = getHeight();
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				graphics.setColor(CHART_BACKGROUND);
				graphics.fillRoundRect(0, 0, width, height, 9, 9);
				int left = 28;
				int right = width - 9;
				int top = 11;
				int bottom = height - 10;
				if (right <= left || activities.isEmpty())
				{
					return;
				}
				graphics.setFont(graphics.getFont().deriveFont(9f));
				graphics.setColor(MUTED);
				graphics.drawString("100", 5, top + 3);
				graphics.drawString("0", 16, bottom + 3);
				graphics.setColor(GRID);
				graphics.drawLine(left, top, right, top);
				graphics.drawLine(left, bottom, right, bottom);
				graphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				double level = charge;
				int pointX = right;
				int pointY = rowForCharge(level, top, bottom);
				for (int index = 0; index < activities.size(); index++)
				{
					BatteryActivityLog.Activity event = activities.get(index);
					level -= event.chargeChange();
					int previousX = right - (right - left) * (index + 1) / activities.size();
					int previousY = rowForCharge(level, top, bottom);
					graphics.setColor(event.isRefill() ? REFILL : DRAIN);
					graphics.drawLine(previousX, previousY, pointX, pointY);
					graphics.fillOval(pointX - 2, pointY - 2, 4, 4);
					pointX = previousX;
					pointY = previousY;
				}
			}
			finally
			{
				graphics.dispose();
			}
		}

		private static int rowForCharge(double charge, int top, int bottom)
		{
			return bottom - (int) Math.round((bottom - top) * Battery.clamp(charge) / Battery.FULL);
		}
	}
}

package com.uniquebattery;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.StringJoiner;

final class BossProgress
{
	private final Map<String, Entry> bosses = new LinkedHashMap<>();

	BossProgress()
	{
		for (String boss : new String[]{"Zulrah", "Vorkath", "Kraken", "General Graardor", "Kree'arra",
			"Commander Zilyana", "K'ril Tsutsaroth"})
		{
			bosses.put(boss.toLowerCase(Locale.ROOT), new Entry(boss, false));
		}
		bosses.put(DoomRates.NAME.toLowerCase(Locale.ROOT), new Entry(DoomRates.NAME, true));
	}

	Entry forBoss(String name)
	{
		return name == null ? null : bosses.get(name.toLowerCase(Locale.ROOT));
	}

	void updateRates(Map<String, Map<String, Double>> uniques)
	{
		bosses.forEach((boss, entry) -> entry.expectedKills = expectedKills(UniqueDrops.forSource(uniques, boss)));
	}

	private static double expectedKills(Map<String, Double> items)
	{
		// Independent-roll approximation for the tracked subset of a drop table.
		double chanceOfMissing = 1;
		for (double denominator : items.values())
		{
			chanceOfMissing *= 1 - 1 / denominator;
		}
		return chanceOfMissing < 1 ? 1 / (1 - chanceOfMissing) : Double.POSITIVE_INFINITY;
	}

	void load(String saved)
	{
		bosses.values().forEach(Entry::reset);
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String row : saved.split(";"))
		{
			String[] fields = row.split("=", 2);
			Entry entry = forBoss(fields[0]);
			if (fields.length == 2 && entry != null)
			{
				try
				{
					entry.read(fields[1]);
				}
				catch (NumberFormatException ignored)
				{
					// A malformed saved entry only affects that boss.
				}
			}
		}
	}

	String save()
	{
		StringJoiner encoded = new StringJoiner(";");
		bosses.forEach((boss, entry) ->
		{
			if (entry.started || entry.dryKills > 0 || entry.seeded)
			{
				encoded.add(boss + "=" + entry.encode());
			}
		});
		return encoded.toString();
	}

	List<Status> statuses()
	{
		List<Status> result = new ArrayList<>();
		for (Entry entry : bosses.values())
		{
			if (entry.started)
			{
				result.add(new Status(entry.name, entry.score(), entry.summary(), entry.baselineNote()));
			}
		}
		return List.copyOf(result);
	}

	static final class Status
	{
		final String name;
		final double score;
		final String details;
		final String baseline;

		private Status(String name, double score, String details, String baseline)
		{
			this.name = name;
			this.score = score;
			this.details = details;
			this.baseline = baseline;
		}
	}

	static final class Entry
	{
		private final String name;
		private final boolean variableDepth;
		private double expectedKills = Double.POSITIVE_INFINITY;
		private int dryKills;
		private double depthExposure;
		private double settledScore;
		private boolean settled;
		private boolean seeded;
		private boolean estimated;
		private boolean started;
		private long completions;
		private long activeTicks;

		private Entry(String name, boolean variableDepth)
		{
			this.name = name;
			this.variableDepth = variableDepth;
		}

		private void reset()
		{
			dryKills = 0;
			depthExposure = 0;
			settledScore = 0;
			settled = false;
			seeded = false;
			estimated = false;
			started = false;
			completions = 0;
			activeTicks = 0;
		}

		void recordActiveTick()
		{
			activeTicks++;
		}

		boolean startTracking()
		{
			if (started)
			{
				return false;
			}
			started = true;
			return true;
		}

		void complete(int count, boolean unique)
		{
			complete(count, unique, 0);
		}

		void complete(int count, boolean unique, double exposure)
		{
			startTracking();
			completions += count;
			dryKills = (int) Math.min(Integer.MAX_VALUE, (long) dryKills + count);
			depthExposure += exposure;
			settled = unique;
			if (unique)
			{
				double atRate = variableDepth ? 1 : Math.round(expectedKills) / expectedKills;
				settledScore = Math.max(0, exposure() - atRate);
				dryKills = 0;
				depthExposure = 0;
				seeded = true;
				estimated = false;
			}
		}

		boolean seed(int count, int uniques)
		{
			if (seeded || (!variableDepth && !Double.isFinite(expectedKills)))
			{
				return false;
			}
			if (variableDepth)
			{
				depthExposure = Math.max(depthExposure, count * DoomRates.deepDelveExposure() - uniques);
			}
			else
			{
				long conservativeKills = Math.round(Math.max(0, count - uniques * expectedKills));
				dryKills = (int) Math.max(dryKills, conservativeKills);
			}
			seeded = true;
			estimated = true;
			startTracking();
			return true;
		}

		private double exposure()
		{
			return variableDepth ? depthExposure : dryKills / expectedKills;
		}

		double score()
		{
			return settled ? settledScore : -exposure();
		}

		boolean hasBaseline()
		{
			return seeded;
		}

		String summary()
		{
			String pace = completions == 0 || activeTicks < 100 ? "Measuring completion pace"
				: String.format(Locale.ROOT, "%.1f completions/h", completions * 6_000.0 / activeTicks);
			if (variableDepth)
			{
				return pace + String.format(Locale.ROOT, "\n%.2f expected gear uniques", exposure());
			}
			if (!Double.isFinite(expectedKills))
			{
				return pace;
			}
			return pace + String.format(Locale.ROOT, "\n%,d dry · ~%,d kills per unique", dryKills, Math.round(expectedKills));
		}

		private String baselineNote()
		{
			if (!seeded)
			{
				return "Open this boss’s Collection Log page once.";
			}
			return estimated ? "Collection Log estimate" : "Tracking observed drops";
		}

		private String encode()
		{
			int flags = 16 | (seeded ? 1 : 0) | (estimated ? 2 : 0) | (settled ? 4 : 0) | (started ? 8 : 0);
			return dryKills + "," + depthExposure + "," + settledScore + "," + flags;
		}

		private void read(String value)
		{
			String[] fields = value.split(",", -1);
			int count = Math.max(0, Integer.parseInt(fields[0]));
			if (fields.length == 1)
			{
				dryKills = count;
				started = count > 0;
				return;
			}
			if (fields.length != 4)
			{
				return;
			}
			double exposure = Double.parseDouble(fields[1]);
			double score = Double.parseDouble(fields[2]);
			int flags = Integer.parseInt(fields[3]);
			if (Double.isFinite(exposure) && exposure >= 0 && Double.isFinite(score) && score >= 0)
			{
				dryKills = count;
				depthExposure = exposure;
				settledScore = score;
				seeded = (flags & 1) != 0;
				estimated = (flags & 2) != 0;
				settled = (flags & 4) != 0;
				started = (flags & 16) != 0 ? (flags & 8) != 0 : count > 0 || settled;
			}
		}
	}
}

package com.uniquebattery;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

final class BossingLadder
{
	enum Tier
	{
		EASY, MEDIUM, HARD, ELITE, MASTER, GRANDMASTER
	}

	// OSRS Wiki, Guide:Bossing Ladder, revision 15408640. Names here match RuneLite NPC names.
	// https://oldschool.runescape.wiki/w/Guide:Bossing_Ladder?oldid=15408640
	private static final Map<String, Tier> NPC_TIERS = npcTiers();

	private BossingLadder()
	{
	}

	static Tier npcTier(String npcName, boolean soloGodWars)
	{
		if (npcName == null)
		{
			return null;
		}
		String name = npcName.toLowerCase(Locale.ROOT);
		if (soloGodWars)
		{
			switch (name)
			{
				case "commander zilyana":
				case "k'ril tsutsaroth":
					return Tier.HARD;
				case "kree'arra":
				case "general graardor":
					return Tier.ELITE;
				default:
					break;
			}
		}
		return NPC_TIERS.get(name);
	}

	static boolean isGodWarsGeneral(String name)
	{
		return name != null && npcTier(name, true) != npcTier(name, false);
	}

	static Map<String, Double> readPersonalRates(String settings)
	{
		Map<String, Double> rates = new HashMap<>();
		for (String rule : settings.split(";"))
		{
			String[] fields = rule.split("\\|", -1);
			if (fields.length != 2 || fields[0].isBlank())
			{
				continue;
			}
			try
			{
				double rate = Double.parseDouble(fields[1].trim());
				if (Double.isFinite(rate) && rate >= 0 && rate <= 100)
				{
					rates.put(fields[0].trim().toLowerCase(Locale.ROOT), rate == 0 ? 0.0 : rate);
				}
			}
			catch (NumberFormatException ignored)
			{
				// A malformed override only affects that entry.
			}
		}
		return Map.copyOf(rates);
	}

	static Tier tombsTier(int raidLevel)
	{
		if (raidLevel >= 500)
		{
			return Tier.GRANDMASTER;
		}
		// The ladder starts at 300. Use Elite for lower-invocation runs.
		return raidLevel >= 300 ? Tier.MASTER : Tier.ELITE;
	}

	private static Map<String, Tier> npcTiers()
	{
		Map<String, Tier> tiers = new HashMap<>();
		add(tiers, Tier.EASY, "Brutus|Wintertodt|Tempoross|Obor|Bryophyta|Deranged archaeologist|Scurrius"
			+ "|Ahrim the Blighted|Dharok the Wretched|Guthan the Infested|Karil the Tainted|Torag the Corrupted|Verac the Defiled");
		add(tiers, Tier.MEDIUM, "Shellbane Gryphon|Penance Queen|Amoxliatl|The Hueycoatl|Hespori|Giant Mole"
			+ "|Crazy archaeologist|Chaos Fanatic|Kraken|Sarachnis|King Black Dragon|Zalcano|Thermonuclear smoke devil"
			+ "|The Mimic|Branda the Fire Queen|Eldric the Ice King|Blood Moon|Blue Moon|Eclipse Moon|Mad Angel"
			+ "|Commander Zilyana|K'ril Tsutsaroth|Kree'arra|General Graardor");
		add(tiers, Tier.HARD, "Scorpia|Chaos Elemental|Vet'ion|Calvar'ion|Venenatis|Spindel|Callisto|Artio"
			+ "|Dagannoth Prime|Dagannoth Rex|Dagannoth Supreme|Dawn|Dusk|Skotizo|TzTok-Jad|Demonic gorilla"
			+ "|Tormented Demon|Crystalline Hunllef|Abyssal Sire|Cerberus|Araxxor|Alchemical Hydra|Corporeal Beast|Kalphite Queen");
		add(tiers, Tier.ELITE, "Zulrah|Vorkath|Phantom Muspah|Duke Sucellus|Maggot King|Corrupted Hunllef"
			+ "|The Whisperer|The Leviathan|Vardorvis|Nex|Yama");
		add(tiers, Tier.MASTER, "The Nightmare|Nightmare|Phosani's Nightmare|Demonic Brutus|Doom of Mokhaiotl|The Doom of Mokhaiotl|Sol Heredit|TzKal-Zuk");
		return Map.copyOf(tiers);
	}

	private static void add(Map<String, Tier> tiers, Tier tier, String names)
	{
		for (String name : names.split("\\|"))
		{
			tiers.put(name.toLowerCase(Locale.ROOT), tier);
		}
	}
}

package com.uniquebattery;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

final class CollectionLogBaseline
{
	private static final Pattern COUNTER = Pattern.compile(
		"(?i)^(?<label>.*(?:kill(?:s| count)|deep delves(?: completed)?))\\s*:\\s*(?<count>[0-9][0-9,]*)$");

	private CollectionLogBaseline()
	{
	}

	static int completionCount(String widgetText, boolean doom)
	{
		String plain = Text.removeTags(widgetText.replace("<br>", "\n")).replace('\u00a0', ' ');
		for (String line : plain.split("\\R"))
		{
			Matcher match = COUNTER.matcher(line.trim());
			if (match.matches())
			{
				String label = match.group("label").toLowerCase(Locale.ROOT);
				if (doom ? label.contains("deep delves") : !label.contains("delves"))
				{
					try
					{
						return Integer.parseInt(match.group("count").replace(",", ""));
					}
					catch (NumberFormatException ignored)
					{
						return -1;
					}
				}
			}
		}
		return -1;
	}
}

package com.uniquebattery;

final class DoomRates
{
	static final String NAME = "Doom of Mokhaiotl";
	// Per-floor rates for the three gear uniques, from the OSRS Wiki.
	private static final int[] GEAR_DENOMINATOR = {0, 0, 2500, 2000, 1350, 810, 765, 720, 630, 540};
	private static final int[] GEAR_COUNT = {0, 0, 1, 2, 3, 3, 3, 3, 3, 3};

	private DoomRates()
	{
	}

	static double gearExposure(int depth)
	{
		double exposure = 0;
		for (int level = 2; level <= Math.min(depth, 9); level++)
		{
			exposure += GEAR_COUNT[level] / (double) GEAR_DENOMINATOR[level];
		}
		return exposure + Math.max(0, depth - 9) * deepDelveExposure();
	}

	static double deepDelveExposure()
	{
		return 3.0 / GEAR_DENOMINATOR[9];
	}

	static double itemDenominator(int depth, String item, double fallback)
	{
		String name = item.toLowerCase(java.util.Locale.ROOT);
		int first = "mokhaiotl cloth".equals(name) ? 2
			: name.startsWith("eye of ayak") ? 3 : "avernic treads".equals(name) ? 4 : 0;
		if (first == 0 || depth < first)
		{
			return fallback;
		}
		double miss = 1;
		for (int level = first; level <= Math.min(depth, 9); level++)
		{
			miss *= 1 - 1.0 / GEAR_DENOMINATOR[level];
		}
		miss *= Math.pow(1 - 1.0 / GEAR_DENOMINATOR[9], Math.max(0, depth - 9));
		return 1 / (1 - miss);
	}
}

